package net.civeira.phylax.features.document.templateversion.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.templateversion.domain.TemplateVersion;
import net.civeira.phylax.features.document.templateversion.domain.gateway.TemplateVersionCursor;
import net.civeira.phylax.features.document.templateversion.domain.gateway.TemplateVersionFilter;

class TemplateVersionSlider extends Slider<TemplateVersion> {

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateVersionCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateVersionFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<TemplateVersionFilter, TemplateVersionCursor, Iterator<TemplateVersion>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  TemplateVersionSlider(final Iterator<TemplateVersion> multi, final int limit,
      final BiFunction<TemplateVersionFilter, TemplateVersionCursor, Iterator<TemplateVersion>> gateway,
      final TemplateVersionFilter filter, final TemplateVersionCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param templateVersions
   * @param limit
   * @return
   */
  @Override
  public Iterator<TemplateVersion> next(List<TemplateVersion> templateVersions, int limit) {
    TemplateVersion last = templateVersions.get(templateVersions.size() - 1);
    TemplateVersionCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
